 await writeFile(join(scratch,'proof.sql'),'BEGIN;SET search_path=bitpos,public;\n'+assets+'\n'+drafts.map(n=>'\\ir '+join(root,'drafts',n)).join('\n')+'\nCOMMIT;\n\\ir '+join(root,'fixtures/076-proof-behavior.sql')+'\n');
